num_qubits // 2,  # number of samples\n        replace=False,  # makes sure states are only sampled once\n    )\n\n    def add_cx(qc, bit_string):\n        for qubit, bit in enumerate(reversed(bit_string)):\n            if bit == "1":\n                qc.x(qubit)\n        return qc\n\n    for state in on_states:\n        qc.barrier()  # Barriers are added to help visualize how the functions are created.\n        qc = add_cx(qc, f"{state:0b}")\n        qc.mcx(list(range(num_qubits)), num_qubits)\n        qc = add_cx(qc, f"{state:0b}")\n\n    qc.barrier()\n\n    return qc\n'})}),"\n",(0,l.jsxs)(a.p,{children:["Kita boleh menunjukkan pelaksanaan Circuit kuantum bagi Gate pertanyaan menggunakan kaedah ",(0,l.jsx)(a.code,{children:"draw"})," seperti biasa."]}),"\n",(0,l.jsx)(a.pre,{children:(0,l.jsx)(a.code,{className:"language-python",children:'display(dj_query(3).draw(output="mpl"))\n'})}),"\n",(0,l.jsx)(a.p,{children:(0,l.jsx)(a.img,{alt:"Output of the previous code cell",src:e(89945).A+"",width:"176",height:"303"})}),"\n",(0,l.jsx)(a.p,{children:"Seterusnya kita takrifkan fungsi yang mencipta Circuit Deutsch-Jozsa, mengambil pelaksanaan Circuit kuantum bagi Gate pertanyaan sebagai argumen."}),"\n",(0,l.jsx)(a.pre,{children:(0,l.jsx)(a.code,{className:"language-python",children:"def compile_circuit(function: QuantumCircuit):\n    # Compiles a circuit for use in the Deutsch-Jozsa algorithm.\n\n    n = function.num_qubits - 1\n    qc = QuantumCircuit(n + 1, n)\n    qc.x(n)\n    qc.h(range(n + 1))\n    qc.compose(function, inplace=True)\n    qc.h(range(n))\n    qc.measure(range(n), range(n))\n    return qc\n"})}),"\n",(0,l.jsx)(a.p,{children:"Akhirnya, fungsi yang menjalankan Circuit Deutsch-Jozsa sekali ditakrifkan."}),"\n",(0,l.jsx)(a.pre,{children:(0,l.jsx)(a.code,{className:"language-python",children:'def dj_algorithm(function: QuantumCircuit):\n    # Determine if a function is constant or balanced.\n\n    qc = compile_circuit(function)\n\n    result = AerSimulator()